const express = require('express');
const app = express();
const PORT = 3000;

// Ruta principal requerida para la validación
app.get('/', (req, res) => {
    res.send('<h1>¡Actividad de JavaScript funcionando con éxito!</h1><p>Entorno configurado en VS Code.</p>');
});

app.listen(PORT, () => {
    console.log(`Servidor ejecutándose en http://localhost:${PORT}`);
});